@media (hover: hover) and (pointer: fine) { .toggle:hover { background: color-mix(in oklab, var(--foreground) 5%, transparent); color: var(--foreground); } }

/* Çizim alanı, sağdaki değer ekseni ve altındaki tarih ekseni. */
